head.script:
scwin.init = function(){
	var jsonData=[{"col1":"2", "col2":"타법원"},{"col1":"2", "col2":"타법원","col3":"서울중앙지법","col4":"서울중앙지법"}
				,{"col1":"2", "col2":"해당법원","col3":"성남지원","col4":"성남지원"}];
	dataList1.setJSON(jsonData);
	var sel_sampleData = [
		{"col1":"타법원", "col2":"타법원"},
		{"col1":"해당법원", "col2":"해당법원"}
	];
	dlt_autoComplete.setJSON(sel_sampleData);
	var sel_sampleData2 = [
		{"col1":"서울중앙지법", "col2":"서울중앙지법"},
		{"col1":"성남지원", "col2":"성남지원"},
		{"col1":"테스트", "col2":"테스트"}
	];
	dlt_selectData.setJSON(sel_sampleData2);
	$p.data.setBroadcast(false);
	for(var i=0; i<gridView1.getRowCount(); i++){
		var col1Data = dataList1.getCellData(i, "col1");
		var obj = {};
		if(col1Data == 1){
			obj = {
				inputType : "text"
			}
		}else{
			obj = {
				inputType : "select",
				options : {
					viewType : "icon",
					chooseOption : true
				},
				itemSet : {
					nodeset:"data:dlt_selectData",
					label : "col1",
					value : "col2"
				}
			}
		}
		gridView1.setCellInputType( i , "col3" , obj );
		var obj2 = {};
		if(col1Data == 1){
			obj2 = {
				inputType : "text"
			}
		}else{
			obj2 = {
				inputType : "autoComplete",
				options : {
					viewType : "icon",
					chooseOption : true
				},
				itemSet : {
					nodeset:"data:dlt_autoComplete",
					label : "col1",
					value : "col2"
				}
			}
		}
		gridView1.setCellInputType( i , "col2" , obj2 );
	}
	$p.data.setBroadcast(true);
};
scwin.onpageload = function() {
	scwin.init();
};
scwin.dataList1_oncelldatachange = function(info){
	if(info.colID == "col1"){
		var obj = {};
		if(info.newValue == 1){
			obj = {
				inputType : "text"
			}
		}else{
			obj = {
				inputType : "autoComplete",
				options : {
					viewType : "icon",
					chooseOption : true
				},
				itemSet : {
					nodeset:"data:dlt_selectData",
					label : "col1",
					value : "col2"
				}
			}
		}
		gridView1.setCellInputType( info.rowIndex , "col3" , obj );
		setTimeout(function(){
			gridView1.setFocusedCell(info.rowIndex, "col3", true);
		},1);
	}
};
